Usage Examples
Bicep Samples
A basic example of deploying EventGrid Event Subscription.
param resourceName string = 'acctest0001'
param location string = 'westeurope'
resource eventSubscription 'Microsoft.EventGrid/eventSubscriptions@2021-12-01' = {
scope: storageAccount
name: resourceName
properties: {
deadLetterDestination: null
destination: {
endpointType: 'EventHub'
properties: {
deliveryAttributeMappings: null
resourceId: eventhub.id
}
}
eventDeliverySchema: 'EventGridSchema'
filter: {
includedEventTypes: [
'Microsoft.Storage.BlobCreated'
'Microsoft.Storage.BlobRenamed'
]
}
labels: []
retryPolicy: {
eventTimeToLiveInMinutes: 144
maxDeliveryAttempts: 10
}
}
}
resource namespace 'Microsoft.EventHub/namespaces@2022-01-01-preview' = {
name: resourceName
location: location
properties: {
disableLocalAuth: false
isAutoInflateEnabled: false
publicNetworkAccess: 'Enabled'
zoneRedundant: false
}
sku: {
capacity: 1
name: 'Standard'
tier: 'Standard'
}
}
resource storageAccount 'Microsoft.Storage/storageAccounts@2021-09-01' = {
name: resourceName
location: location
kind: 'StorageV2'
properties: {
accessTier: 'Hot'
allowBlobPublicAccess: true
allowCrossTenantReplication: true
allowSharedKeyAccess: true
defaultToOAuthAuthentication: false
encryption: {
keySource: 'Microsoft.Storage'
services: {
queue: {
keyType: 'Service'
}
table: {
keyType: 'Service'
}
}
}
isHnsEnabled: false
isNfsV3Enabled: false
isSftpEnabled: false
minimumTlsVersion: 'TLS1_2'
networkAcls: {
defaultAction: 'Allow'
}
publicNetworkAccess: 'Enabled'
supportsHttpsTrafficOnly: true
}
sku: {
name: 'Standard_LRS'
}
}
resource eventhub 'Microsoft.EventHub/namespaces/eventhubs@2021-11-01' = {
parent: namespace
name: resourceName
properties: {
messageRetentionInDays: 1
partitionCount: 1
status: 'Active'
}
}
